29	/**
30	 * Basic Log formatter.
31	 *
32	 * @author Luca Garulli
33	 */
34	
35	public class LogFormatter extends Formatter {
36	
37	  protected static final DateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS");
38	
39	  /**
40	   * The end-of-line character for this platform.
41	   */
42	  protected static final String EOL = System.getProperty("line.separator");
43	
44	  @Override
45	  public String format(final LogRecord record) {
46	    final String formatted = customFormatMessage(record);
47	
48	    final Throwable current = record.getThrown();
49	    if (current == null)
50	      return formatted;
51	
52	    final StringBuilder buffer = new StringBuilder(512);
53	    buffer.append(formatted);
54	    buffer.append(EOL);
55	
56	    final StringWriter writer = new StringWriter();
57	    final PrintWriter printWriter = new PrintWriter(writer);
58	    current.printStackTrace(printWriter);
59	    printWriter.flush();
60	    buffer.append(writer.getBuffer());
61	    printWriter.close();
62	
63	    return buffer.toString();
64	  }
65	
66	  protected String customFormatMessage(final LogRecord iRecord) {
67	    final Level level = iRecord.getLevel();
68	    final String message = AnsiCode.format(iRecord.getMessage(), false);
69	    final Object[] additionalArgs = iRecord.getParameters();
70	    final String requester = getSourceClassSimpleName(iRecord.getLoggerName());
71	
72	    final StringBuilder buffer = new StringBuilder(512);
73	    buffer.append(EOL);
74	    synchronized (dateFormat) {
75	      buffer.append(dateFormat.format(new Date()));
76	    }
77	
78	    buffer.append(" %-5.5s ".formatted(level.getName()));
79	
80	    if (requester != null) {
81	      buffer.append("[");
82	      buffer.append(requester);
83	      buffer.append("] ");
84	    }
85	
86	    // FORMAT THE MESSAGE
87	    try {
88	      if (additionalArgs != null)
89	        buffer.append(message.formatted(additionalArgs));
90	      else
91	        buffer.append(message);
92	    } catch (final IllegalFormatException ignore) {
93	      buffer.append(message);
94	    }
95	
96	    return AnsiCode.format(buffer.toString(), false);
97	  }
98	
99	  protected String getSourceClassSimpleName(final String iSourceClassName) {
100	    if (iSourceClassName == null)
101	      return null;
102	    return iSourceClassName.substring(iSourceClassName.lastIndexOf(".") + 1);
103	  }
104	}
