247	function normalizeMessageContentForFullTextIndex(content: string): string | null {
248	  if (typeof content !== "string") return null;
249	  const trimmed = content.trim();
250	  if (!trimmed) {
251	    return null;
252	  }
253	
254	  const isExternalizedReference =
255	    trimmed.startsWith("[LCM File:") || trimmed.startsWith("[LCM Tool Output:");
256	  if (!isExternalizedReference) {
257	    return content;
258	  }
259	
260	  const lines = trimmed
261	    .split(/\r?\n/)
262	    .map((line) => line.trim())
263	    .filter((line) => line.length > 0);
264	  if (lines.length === 0) {
265	    return null;
266	  }
267	
268	  const header = lines[0] ?? "";
269	  const summaryLines: string[] = [];
270	  let inSummary = false;
271	  for (let index = 1; index < lines.length; index += 1) {
272	    const line = lines[index]!;
273	    if (line === "Exploration Summary:") {
274	      inSummary = true;
275	      continue;
276	    }
277	    // Filter both legacy "Use lcm_describe …" and v4.2 "Call lcm_describe(…)"
278	    // hint lines so they don't pollute the FTS index for unrelated queries.
279	    if (line.startsWith("Use lcm_describe") || line.startsWith("Call lcm_describe")) {
280	      continue;
281	    }
282	    if (inSummary) {
283	      summaryLines.push(line);
284	    }
285	  }
286	
287	  const normalized = [header, ...summaryLines].filter((line) => line.length > 0).join("\n");
288	  return normalized || null;
289	}
