256	                .log("Replaying entries for deduplication");
257	        return replayTask.replay(cursor, (__, buffer) -> {
258	            final var metadata = Commands.parseMessageMetadata(buffer);
259	            final var producerName = metadata.getProducerName();
260	            final var sequenceId = Math.max(metadata.getHighestSequenceId(), metadata.getSequenceId());
261	            highestSequencedPushed.put(producerName, sequenceId);
262	            highestSequencedPersisted.put(producerName, sequenceId);
263	            producerRemoved(producerName);
264	        }).thenCompose(optPosition -> {
265	            if (optPosition.isEmpty()) {
266	                return CompletableFuture.completedFuture(null);
267	            }
268	            snapshotCounter = replayTask.getNumEntriesProcessed();
269	            if (snapshotCounter >= snapshotInterval) {
270	                return takeSnapshot(optPosition.get());
