77	/// Returns `true` if a comment contains Python code.
78	pub(crate) fn comment_contains_code(line: &str, task_tags: &[String]) -> bool {
79	    let line = line
80	        .trim_start_matches(|char| char == '#' || is_python_whitespace(char))
81	        .trim_end();
82	
83	    // Fast path: if none of the indicators are present, the line is not code.
84	    if !CODE_INDICATORS.is_match(line) {
85	        return false;
86	    }
87	
88	    // Fast path: if the comment contains consecutive identifiers, we know it won't parse.
89	    let tokenizer = SimpleTokenizer::starts_at(TextSize::default(), line).skip_trivia();
90	    if tokenizer.tuple_windows().any(|(first, second)| {
91	        first.kind == SimpleTokenKind::Name && second.kind == SimpleTokenKind::Name
92	    }) {
93	        return false;
94	    }
95	
96	    // Ignore task tag comments (e.g., "# TODO(tom): Refactor").
97	    if line
98	        .split(&[' ', ':', '('])
99	        .next()
100	        .is_some_and(|first| task_tags.iter().any(|tag| tag == first))
101	    {
102	        return false;
103	    }
104	
105	    // Ignore whitelisted comments.
106	    if ALLOWLIST_REGEX.is_match(line) {
107	        return false;
108	    }
109	
110	    // Ignore non-comment related hashes (e.g., "# Issue #999").
111	    if HASH_NUMBER.is_match(line) {
112	        return false;
113	    }
114	
115	    // If the comment made it this far, and ends in a continuation, assume it's code.
116	    if line.ends_with('\\') {
117	        return true;
118	    }
119	
120	    // If the comment matches any of the specified positive cases, assume it's code.
121	    if POSITIVE_CASES.is_match(line) {
122	        return true;
123	    }
124	
125	    // Finally, compile the source code.
126	    parse_module(line).is_ok()
127	}
