10	pub(crate) fn get_module_prefix(source: &str, offset: usize) -> Option<&str> {
11	    let before = &source[..offset];
12	    if !before.ends_with('.') {
13	        return None;
14	    }
15	    let before_dot = &before[..before.len() - 1];
16	
17	    let base = if before_dot.ends_with(']') {
18	        let bracket_start = before_dot.rfind('[')?;
19	        &before_dot[..bracket_start]
20	    } else {
21	        before_dot
22	    };
23	
24	    let start = base
25	        .rfind(|c: char| !c.is_alphanumeric() && c != '_')
26	        .map(|i| i + 1)
27	        .unwrap_or(0);
28	    let identifier = base[start..].trim();
29	    if identifier.is_empty() || !identifier.starts_with(|c: char| c.is_alphabetic() || c == '_') {
30	        return None;
31	    }
32	    Some(identifier)
33	}
