69	/// Resolve a variable name to its type's qualified name by scanning usages.
70	/// When `indexed` is true, extracts the element type for collection types.
71	pub(crate) fn resolve_variable_type(
72	    var_name: &str,
73	    file: &syntax::program::File,
74	    offset: u32,
75	    snapshot: &AnalysisSnapshot,
76	    indexed: bool,
77	) -> Option<String> {
78	    let binding =
79	        snapshot.facts().bindings.values().find(|b| {
80	            b.name == var_name && b.span.file_id == file.id && b.span.byte_offset < offset
81	        })?;
82	
83	    let expression = find_expression_at(&file.items, binding.span.byte_offset)?;
84	    let borrowed_ty = match expression {
85	        Expression::Let {
86	            binding: let_binding,
87	            ..
88	        } => {
89	            let matches_name = match &let_binding.pattern {
90	                syntax::ast::Pattern::Identifier { identifier, .. } => identifier == var_name,
91	                syntax::ast::Pattern::AsBinding { name, .. } => name == var_name,
92	                _ => false,
93	            };
94	            if matches_name {
95	                Some(&let_binding.ty)
96	            } else {
97	                None
98	            }
99	        }
100	        Expression::Identifier { ty, .. } => Some(ty),
101	        Expression::For {
102	            binding: for_binding,
103	            ..
104	        } => Some(&for_binding.ty),
105	        Expression::Function { params, .. } | Expression::Lambda { params, .. } => {
106	            let param = params.iter().find(|p| match &p.pattern {
107	                syntax::ast::Pattern::Identifier { identifier, .. } => identifier == var_name,
108	                syntax::ast::Pattern::AsBinding { name, .. } => name == var_name,
109	                _ => false,
110	            })?;
111	            Some(&param.ty)
112	        }
113	        _ => None,
114	    };
115	
116	    let owned_ty;
117	    let ty = if let Some(t) = borrowed_ty {
118	        t
119	    } else {
120	        let (t, _) = crate::hover::get_hover_type_and_span(expression, binding.span.byte_offset);
121	        owned_ty = t;
122	        &owned_ty
123	    };
124	
125	    let (resolved, _) = syntax::types::Type::remove_vars(&[ty]);
126	    let ty = &resolved[0];
127	
128	    if indexed {
129	        element_type_name(ty)
130	    } else {
131	        type_name(ty)
132	    }
133	}
