140	pub(crate) fn detect_dot_context(
141	    file: &syntax::program::File,
142	    offset: u32,
143	    snapshot: &AnalysisSnapshot,
144	) -> Option<DotContext> {
145	    let Expression::DotAccess {
146	        expression, member, ..
147	    } = find_expression_at(&file.items, offset.saturating_sub(1))?
148	    else {
149	        return None;
150	    };
151	    if !member.is_empty() {
152	        if !matches!(
153	            get_root_expression(expression),
154	            Expression::Identifier {
155	                binding_id: None,
156	                ..
157	            }
158	        ) {
159	            let ty = expression.get_type();
160	            return type_name(&ty).map(DotContext::Instance);
161	        }
162	        return None;
163	    }
164	
165	    if let Expression::Identifier { value, .. } = expression.as_ref() {
166	        for prefix in [file.module_id.as_str(), "prelude"] {
167	            let qualified = format!("{prefix}.{value}");
168	            if let Some(definition) = snapshot.definitions().get(qualified.as_str())
169	                && definition.is_type_definition()
170	            {
171	                return Some(DotContext::TypeLevel(qualified));
172	            }
173	        }
174	    }
175	
176	    let ty = expression.get_type();
177	    if let Some(type_id) = type_name(&ty) {
178	        return Some(DotContext::Instance(type_id));
179	    }
180	
181	    if let Expression::Identifier { value, .. } = expression.as_ref()
182	        && value == "self"
183	        && let Some(impl_type) = find_enclosing_impl_type(&file.items, offset)
184	    {
185	        let qualified = format!("{}.{}", file.module_id, impl_type);
186	        return Some(DotContext::Instance(qualified));
187	    }
188	
189	    None
190	}
