94	fn format(
95	    output: &mut String,
96	    limit: isize,
97	    mut width: isize,
98	    mut docs: Vec<(isize, Mode, &Document<'_>)>,
99	) {
100	    let mut pending_indent: isize = -1;
101	
102	    while let Some((indent, mode, document)) = docs.pop() {
103	        match document {
104	            Document::Newline => {
105	                output.push('\n');
106	                pending_indent = indent;
107	                width = indent;
108	            }
109	
110	            Document::FlexBreak { broken, unbroken } => {
111	                let unbroken_width = width + unbroken.len() as isize;
112	                if mode == Mode::Unbroken || fits(limit, unbroken_width, docs.clone()) {
113	                    if pending_indent >= 0 {
114	                        write_indent(output, pending_indent);
115	                        pending_indent = -1;
116	                    }
117	                    output.push_str(unbroken);
118	                    width = unbroken_width;
119	                } else {
120	                    if pending_indent >= 0 {
121	                        write_indent(output, pending_indent);
122	                    }
123	                    output.push_str(broken);
124	                    output.push('\n');
125	                    pending_indent = indent;
126	                    width = indent;
127	                }
128	            }
129	
130	            Document::StrictBreak { broken, unbroken } => match mode {
131	                Mode::Broken | Mode::ForcedBroken => {
132	                    if pending_indent >= 0 {
133	                        write_indent(output, pending_indent);
134	                    }
135	                    output.push_str(broken);
136	                    output.push('\n');
137	                    pending_indent = indent;
138	                    width = indent;
139	                }
140	                Mode::Unbroken | Mode::ForcedUnbroken => {
141	                    if pending_indent >= 0 {
142	                        write_indent(output, pending_indent);
143	                        pending_indent = -1;
144	                    }
145	                    output.push_str(unbroken);
146	                    width += unbroken.len() as isize;
147	                }
148	            },
149	
150	            Document::Text(s) => {
151	                if pending_indent >= 0 {
152	                    write_indent(output, pending_indent);
153	                    pending_indent = -1;
154	                }
155	                width += s.graphemes(true).count() as isize;
156	                output.push_str(s);
157	            }
158	
159	            Document::VerbatimText(s) => {
160	                if pending_indent >= 0 {
161	                    write_indent(output, pending_indent);
162	                    pending_indent = -1;
163	                }
164	                let mut segments = s.split('\n');
165	                if let Some(first) = segments.next() {
166	                    output.push_str(first);
167	                    width += first.graphemes(true).count() as isize;
168	                }
169	                for segment in segments {
170	                    output.push('\n');
171	                    output.push_str(segment);
172	                    width = segment.graphemes(true).count() as isize;
173	                }
174	            }
175	
176	            Document::Sequence(vec) => {
177	                for doc in vec.iter().rev() {
178	                    docs.push((indent, mode, doc));
179	                }
180	            }
181	
182	            Document::Nest(i, doc) => {
183	                docs.push((indent + i, mode, doc));
184	            }
185	
186	            Document::NestIfBroken(i, doc) => {
187	                if mode == Mode::Broken {
188	                    docs.push((indent + i, mode, doc));
189	                } else {
190	                    docs.push((indent, mode, doc));
191	                }
192	            }
193	
194	            Document::Group(doc) => {
195	                let group_docs = vec![(indent, Mode::Unbroken, doc.as_ref())];
196	                if fits(limit, width, group_docs) {
197	                    docs.push((indent, Mode::Unbroken, doc));
198	                } else {
199	                    docs.push((indent, Mode::Broken, doc));
200	                }
201	            }
202	
203	            Document::ForceBroken(document) | Document::NextBreakFits(document, _) => {
204	                docs.push((indent, mode, document));
205	            }
206	        }
207	    }
