340	// collectTextFieldNamesFromFields picks searchable scalar string fields
341	// out of an already-resolved response field list. Keeps the FTS index
342	// pinned to fields sync actually stores — request-side filter knobs like
343	// `tags` or `labels` never appear here because they aren't in the
344	// response schema.
345	func collectTextFieldNamesFromFields(fields []spec.TypeField) []string {
346		seen := make(map[string]bool)
347		var result []string
348		for _, f := range fields {
349			lower := strings.ToLower(f.Name)
350			if !textFieldKeywords[lower] || seen[lower] || !isScalarTypeField(f) {
351				continue
352			}
353			seen[lower] = true
354			result = append(result, toSnakeCase(f.Name))
355		}
