371	// a foreign key column referencing the parent table. Sub-resources share
372	// the base id/data/synced_at shape with top-level tables and add a
373	// parent_id column between id and data.
374	func buildSubResourceTable(name string, r spec.Resource, parentTable string) TableDef {
375		tableName := toSnakeCase(name)
376		parentCol := parentTable + "_id"
377	
378		columns := make([]ColumnDef, 0, len(baseTableColumns)+1)
379		columns = append(columns, baseTableColumns[0]) // id
380		columns = append(columns, ColumnDef{Name: parentCol, Type: "TEXT", NotNull: true})
381		columns = append(columns, baseTableColumns[1:]...) // data, synced_at
382	
383		return TableDef{
384			Name:     tableName,
385			Resource: tableName,
386			Columns:  columns,
387			Indexes: []IndexDef{
388				{
389					Name:      "idx_" + tableName + "_" + parentCol,
390					TableName: tableName,
391					Columns:   parentCol,
392				},
393			},
394		}
