143	/// Produce the prop-options string for a single defineModel, stripping the
144	/// runtime-only `get`/`set` accessors (which belong only on the `useModel`
145	/// runtime argument), matching `@vue/compiler-sfc`'s `genModelProps`.
146	fn strip_runtime_accessors(opts: &str) -> Option<String> {
147	    let (open, close) = find_object_close(opts)?;
148	    let props = parse_option_props(opts, open, close)?;
149	    // Build result by removing get/set spans from last to first, mirroring Vue's
150	    // `slice(0, start) + slice(end)` where `end = next ? next.start : close`.
151	    let mut result = opts.to_compact_string();
152	    for idx in (0..props.len()).rev() {
153	        let p = &props[idx];
154	        if p.key == "get" || p.key == "set" {
155	            let end = props.get(idx + 1).map(|n| n.start).unwrap_or(close);
156	            result.replace_range(p.start..end, "");
157	        }
158	    }
