126	fn classify_response_schema(
127	    path: &str,
128	    schema: &Value,
129	) -> (OutputCardinality, Vec<String>, Value, Option<String>) {
130	    if schema == &Value::Null {
131	        return (OutputCardinality::None, Vec::new(), Value::Null, None);
132	    }
133	    if schema.get("type").and_then(Value::as_str) == Some("array") {
134	        let item = schema.get("items").cloned().unwrap_or(Value::Null);
135	        return (
136	            OutputCardinality::List,
137	            Vec::new(),
138	            item.clone(),
139	            item.get("$ref")
140	                .and_then(Value::as_str)
141	                .map(entity_name_from_ref),
142	        );
143	    }
144	    if schema
145	        .get("type")
146	        .and_then(Value::as_str)
147	        .unwrap_or("object")
148	        == "object"
149	    {
150	        if let Some((property_name, items)) = schema
151	            .get("properties")
152	            .and_then(Value::as_object)
153	            .and_then(wrapped_list_property)
154	        {
155	            let item = items.get("items").cloned().unwrap_or(Value::Null);
156	            return (
157	                OutputCardinality::WrappedList,
158	                vec![property_name.to_string()],
159	                item.clone(),
160	                item.get("$ref")
161	                    .and_then(Value::as_str)
162	                    .map(entity_name_from_ref),
163	            );
164	        }
165	        return (
166	            OutputCardinality::Singleton,
167	            Vec::new(),
168	            schema.clone(),
169	            schema
170	                .get("$ref")
171	                .and_then(Value::as_str)
172	                .map(entity_name_from_ref)
173	                .or_else(|| Some(entity_name_from_path(path))),
174	        );
175	    }
176	    (OutputCardinality::Unknown, Vec::new(), schema.clone(), None)
177	}
