179	fn wrapped_list_property(properties: &Map<String, Value>) -> Option<(&str, &Value)> {
180	    ["items", "data", "results", "rows"]
181	        .iter()
182	        .find_map(|name| {
183	            properties
184	                .get(*name)
185	                .filter(|property| property.get("type").and_then(Value::as_str) == Some("array"))
186	                .map(|property| (*name, property))
187	        })
188	        .or_else(|| single_array_payload_property(properties))
189	}
