194	        .filter(|(_, property)| property.get("type").and_then(Value::as_str) == Some("array"))
195	        .filter(|(name, _)| !is_wrapper_metadata_property(name))
196	        .collect::<Vec<_>>();
197	    match array_properties.as_slice() {
198	        [(name, property)] => Some((name.as_str(), *property)),
199	        [] | [_, _, ..] => None,
200	    }
201	}
