41	impl<'a> OpenApiImporter<'a> {
42	    fn new(manifest: &'a V4SourceManifest, surface: &'a V4Surface, document: &'a Value) -> Self {
43	        Self {
44	            manifest,
45	            surface,
46	            document,
47	            types: BTreeMap::new(),
48	            diagnostics: Vec::new(),
49	        }
50	    }
