52	    fn import(&mut self) -> Result<SemanticIr> {
53	        let paths = self
54	            .document
55	            .get("paths")
56	            .and_then(Value::as_object)
57	            .ok_or_else(|| ManifestError::validation("OpenAPI document is missing paths"))?;
58	        let mut operations = Vec::new();
59	        let mut operation_ids = HashSet::new();
60	        for (path, path_item) in paths {
61	            let Some(path_item) = path_item.as_object() else {
62	                continue;
63	            };
64	            for method_name in [
65	                "get", "head", "options", "post", "put", "patch", "delete", "trace",
66	            ] {
67	                let Some(operation_value) = path_item.get(method_name) else {
68	                    continue;
69	                };
70	                let operation =
71	                    self.import_operation(path, path_item, method_name, operation_value)?;
72	                if !operation_ids.insert(operation.id.clone()) {
