74	                        "source '{}' surface '{}' imports duplicate operation id '{}'",
75	                        self.manifest.common.name, self.surface.id, operation.id
76	                    )));
77	                }
78	                operations.push(operation);
79	            }
80	        }
81	        Ok(SemanticIr {
82	            artifact_schema_version: V4_ARTIFACT_SCHEMA_VERSION,
83	            source_name: self.manifest.common.name.clone(),
84	            surface_id: self.surface.id.clone(),
85	            surface_type: self.surface.surface_type,
86	            importer_version: OPENAPI_IMPORTER_VERSION.to_string(),
87	            operations,
88	            types: self.types.values().cloned().collect(),
89	            diagnostics: self.diagnostics.clone(),
90	        })
91	    }
