94	        &self,
95	        value: &Value,
96	        operation_id: &str,
97	        diagnostics: &mut Vec<Diagnostic>,
98	    ) -> Option<Value> {
99	        let Some(reference) = value.get("$ref").and_then(Value::as_str) else {
