105	                format!("external reference '{reference}' is unsupported"),
106	                self.surface.id.clone(),
107	                Some(operation_id.to_string()),
108	            ));
109	            return None;
110	        }
111	        let pointer = reference.strip_prefix('#').unwrap_or(reference);
