113	            Some(target.clone())
114	        } else {
115	            diagnostics.push(Diagnostic::warning(
116	                "OPENAPI_REF_NOT_FOUND",
117	                format!("reference '{reference}' was not found"),
118	                self.surface.id.clone(),
119	                Some(operation_id.to_string()),
120	            ));
