158	        properties
159	            .iter()
160	            .map(|(name, schema)| {
161	                let type_ref = self
162	                    .import_schema(
163	                        schema,
164	                        &format!("{parent_id}_{name}"),
165	                        operation_id,
166	                        diagnostics,
167	                    )
168	                    .unwrap_or_else(|| "json".to_string());
169	                IrField {
170	                    name: name.clone(),
171	                    type_ref,
172	                    required: required.contains(name),
173	                    nullable: true,
174	                    description: self.field_description(schema),
175	                }
176	            })
177	            .collect()
178	    }
