35	public class LogFormatter extends Formatter {
36	
37	  protected static final DateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS");
38	
39	  /**
40	   * The end-of-line character for this platform.
41	   */
42	  protected static final String EOL = System.getProperty("line.separator");
43	
44	  @Override
45	  public String format(final LogRecord record) {
46	    final String formatted = customFormatMessage(record);
47	
48	    final Throwable current = record.getThrown();
49	    if (current == null)
50	      return formatted;
51	
52	    final StringBuilder buffer = new StringBuilder(512);
53	    buffer.append(formatted);
54	    buffer.append(EOL);
55	
56	    final StringWriter writer = new StringWriter();
57	    final PrintWriter printWriter = new PrintWriter(writer);
58	    current.printStackTrace(printWriter);
59	    printWriter.flush();
60	    buffer.append(writer.getBuffer());
61	    printWriter.close();
62	
63	    return buffer.toString();
64	  }
