39	    final Object[] additionalArgs = iRecord.getParameters();
40	    final String requester = getSourceClassSimpleName(iRecord.getLoggerName());
41	
42	    final StringBuilder buffer = new StringBuilder(512);
43	    buffer.append(EOL);
44	
45	    if (AnsiCode.supportsColors())
46	      buffer.append("$ANSI{cyan ");
47	    synchronized (dateFormat) {
48	      buffer.append(dateFormat.format(new Date()));
49	    }
50	
51	    if (AnsiCode.supportsColors())
52	      buffer.append("}");
53	
54	    if (AnsiCode.supportsColors()) {
55	      if (level == SEVERE)
56	        buffer.append("$ANSI{red ");
57	      else if (level == Level.WARNING)
58	        buffer.append("$ANSI{yellow ");
59	      else if (level == Level.INFO)
60	        buffer.append("$ANSI{green ");
61	      else
62	        // DEFAULT
63	        buffer.append("$ANSI{white ");
64	    }
65	
66	    buffer.append(" %-5.5s ".formatted(level.getName()));
67	    if (AnsiCode.supportsColors())
68	      buffer.append("}");
69	
70	    if (requester != null) {
71	      buffer.append("[");
72	      buffer.append(requester);
73	      buffer.append("] ");
74	    }
75	
76	    // FORMAT THE MESSAGE
77	    try {
78	      if (additionalArgs != null)
79	        buffer.append(message.formatted(additionalArgs));
80	      else
81	        buffer.append(message);
82	    } catch (final IllegalFormatException ignore) {
83	      buffer.append(message);
84	    }
85	
86	    return AnsiCode.format(buffer.toString());
