171	/// Unlike [`analyze_template_snippet`], this does NOT filter against imported bindings.
172	/// Returns `(identifiers, member_accesses)`. Used by the Angular template scanner
173	/// for external templates where unresolved identifiers are potential component
174	/// class member refs and member-access chains (`dataService.getTotal()`) must
175	/// be resolved against the component's constructor-injected type bindings to
176	/// credit the target class's member as used.
177	pub fn collect_unresolved_refs_and_accesses(
178	    snippet: &str,
179	    kind: TemplateSnippetKind,
180	    locals: &[String],
181	) -> (FxHashSet<String>, Vec<MemberAccess>) {
182	    let snippet = snippet.trim();
183	    if snippet.is_empty() {
184	        return (FxHashSet::default(), Vec::new());
185	    }
186	
187	    let wrapped = wrap_snippet(snippet, kind, locals);
188	    let allocator = Allocator::default();
189	    let parser_return = Parser::new(&allocator, &wrapped, SourceType::ts()).parse();
190	    let semantic_ret = SemanticBuilder::new().build(&parser_return.program);
191	
192	    let unresolved_names: FxHashSet<String> = semantic_ret
193	        .semantic
194	        .scoping()
195	        .root_unresolved_references()
196	        .keys()
197	        .map(|name| name.to_string())
198	        .collect();
199	
200	    if unresolved_names.is_empty() {
201	        return (unresolved_names, Vec::new());
202	    }
203	
204	    let mut extractor = ModuleInfoExtractor::new();
205	    extractor.visit_program(&parser_return.program);
206	    let member_accesses = dedup_member_accesses(
207	        extractor
208	            .member_accesses
209	            .into_iter()
210	            .filter(|access| unresolved_names.contains(&access.object))
