217	fn remap_object_name(
218	    name: &str,
219	    unresolved_names: &FxHashSet<String>,
220	    bound_targets: &FxHashMap<String, String>,
221	    allow_dollar_prefixed_refs: bool,
222	) -> Option<String> {
223	    if unresolved_names.contains(name) {
224	        if let Some(target) = bound_targets.get(name) {
225	            return Some(target.clone());
226	        }
227	        return Some(name.to_string());
228	    }
229	    if allow_dollar_prefixed_refs
230	        && let Some(stripped) = name.strip_prefix('$')
231	        && unresolved_names.contains(stripped)
232	    {
233	        if let Some(target) = bound_targets.get(stripped) {
234	            return Some(target.clone());
235	        }
236	        return Some(stripped.to_string());
237	    }
238	    None
239	}
