241	fn wrap_snippet(snippet: &str, kind: TemplateSnippetKind, locals: &[String]) -> String {
242	    let mut wrapped = String::new();
243	    if !locals.is_empty() {
244	        wrapped.push_str("const __fallow_local = undefined;\n");
245	        for local in locals {
246	            wrapped.push_str("const ");
247	            wrapped.push_str(local);
248	            wrapped.push_str(" = __fallow_local;\n");
249	        }
250	    }
251	
252	    match kind {
253	        TemplateSnippetKind::Expression => {
254	            wrapped.push_str("void (");
255	            wrapped.push_str(snippet);
256	            wrapped.push_str(");\n");
257	        }
258	        TemplateSnippetKind::Statement => {
259	            wrapped.push_str("(() => {\n");
260	            wrapped.push_str(snippet);
261	            wrapped.push_str("\n})();\n");
262	        }
263	    }
264	
265	    wrapped
266	}
