268	fn dedup_member_accesses(accesses: Vec<MemberAccess>) -> Vec<MemberAccess> {
269	    let mut seen: FxHashSet<(String, String)> = FxHashSet::default();
270	    let mut deduped = Vec::with_capacity(accesses.len());
271	    for access in accesses {
272	        let key = (access.object.clone(), access.member.clone());
273	        if seen.insert(key) {
274	            deduped.push(access);
275	        }
276	    }
277	    deduped
278	}
279	
280	fn dedup_names(names: Vec<String>) -> Vec<String> {
281	    let mut seen: FxHashSet<String> = FxHashSet::default();
282	    let mut deduped = Vec::with_capacity(names.len());
283	    for name in names {
284	        if seen.insert(name.clone()) {
285	            deduped.push(name);
286	        }
287	    }
288	    deduped
289	}
